// Project adapter around Beav's xhsBridge. It never accesses browser cookies or credentials.
const DEFAULT_ENDPOINT = 'http://localhost:5173/api/signals/ingest';
const tasks = new Map();
const xhsUrl = (url) => /^https:\/\/(www\.)?(xiaohongshu\.com|rednote\.com)\//.test(url || '');

async function endpoint() { return (await chrome.storage.local.get('endpoint')).endpoint || DEFAULT_ENDPOINT; }
function createTask(method) { const task = { id: crypto.randomUUID(), method, status: 'queued', createdAt: new Date().toISOString(), cancelled: false }; tasks.set(task.id, task); return task; }
async function pageResponses(tabId) { const [{ result = [] } = {}] = await chrome.scripting.executeScript({ target: { tabId }, world: 'MAIN', func: () => window.__REDBOX_XHS_RESPONSES__ || [] }); return result; }
function candidates(records) { const found = new Map(); const visit = (value, seen = new WeakSet()) => { if (!value || typeof value !== 'object' || seen.has(value)) return; seen.add(value); const card = value.note_card || value.noteCard || value.note || value; const noteId = card.note_id || card.noteId; if (noteId && (card.title || card.desc || card.user || card.author)) found.set(String(noteId), card); for (const child of Object.values(value)) visit(child, seen); }; records.forEach((record) => visit(record?.result)); return [...found.values()]; }
async function collectVisibleNotes(tab, task) { task.status = 'running'; const records = await pageResponses(tab.id); if (task.cancelled) throw new Error('任务已取消'); const signals = candidates(records).map((raw) => ({ ...raw, source: { provider: 'beav-derived-browser-extension', method: 'visible-notes', taskId: task.id, capturedAt: new Date().toISOString() } })); if (!signals.length) throw new Error('当前页面尚未观察到可采集的公开笔记。请刷新页面后再试。'); const response = await fetch(await endpoint(), { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ signals }) }); const payload = await response.json().catch(() => ({})); if (!response.ok) throw new Error(payload.error || '本地工作台拒绝了采集数据'); task.status = 'completed'; task.result = payload; return payload; }

// Provider interface: current/visible are active in Batch 01; other methods are reserved and explicitly unsupported.
const provider = { collectCurrentNote: collectVisibleNotes, collectVisibleNotes, collectKeyword: async () => { throw new Error('Batch 01 尚未支持关键词采集'); }, collectCreator: async () => { throw new Error('Batch 01 尚未支持博主采集'); }, collectComments: async () => { throw new Error('Batch 01 尚未支持评论采集'); } };
chrome.runtime.onMessage.addListener((message, _sender, respond) => { (async () => { if (message.type === 'collector:config') { const value = await chrome.storage.local.get('endpoint'); return respond({ endpoint: value.endpoint || DEFAULT_ENDPOINT }); } if (message.type === 'collector:set-endpoint') { await chrome.storage.local.set({ endpoint: message.endpoint || DEFAULT_ENDPOINT }); return respond({ ok: true }); } if (message.type === 'collector:cancel') { const task = tasks.get(message.taskId); if (task) task.cancelled = true; return respond({ ok: Boolean(task) }); } if (message.type !== 'collector:collect') return respond({ error: '未知请求' }); const [tab] = await chrome.tabs.query({ active: true, currentWindow: true }); if (!tab || !xhsUrl(tab.url)) return respond({ error: '请先打开小红书或 RedNote 的公开页面。' }); const task = createTask(message.method || 'visible-notes'); try { return respond({ task, result: await provider.collectVisibleNotes(tab, task) }); } catch (error) { task.status = task.cancelled ? 'cancelled' : 'failed'; task.error = error.message; return respond({ task, error: error.message }); } })(); return true; });
